-- ASTRA AURA v37 monetization + expanded numerology
alter table public.numerology_knowledge
  add column if not exists essence text,
  add column if not exists relationships text,
  add column if not exists money text,
  add column if not exists realization text,
  add column if not exists purpose text,
  add column if not exists practical_advice text;

create table if not exists public.numerology_purchases (
  id bigserial primary key,
  telegram_user_id bigint not null,
  username text,
  product_key text not null,
  payload text not null,
  currency text not null,
  amount bigint not null,
  telegram_charge_id text unique not null,
  created_at timestamptz not null default now()
);

alter table public.numerology_purchases enable row level security;
revoke all on public.numerology_purchases from anon, authenticated;

create index if not exists numerology_purchases_user_idx
  on public.numerology_purchases(telegram_user_id, created_at desc);

-- Expand the core 1-9 and master numbers with human-readable premium fields.
update public.numerology_knowledge set
 essence = case key
  when '1' then 'Энергия самостоятельности, инициативы и внутреннего стержня.'
  when '2' then 'Тонкое восприятие, дипломатия и способность чувствовать людей.'
  when '3' then 'Самовыражение, живость, творчество и потребность делиться собой.'
  when '4' then 'Опора, порядок, ответственность и умение превращать планы в результат.'
  when '5' then 'Свобода, движение, любопытство и любовь к переменам.'
  when '6' then 'Забота, ответственность, красота и стремление создавать гармонию.'
  when '7' then 'Глубина, анализ, поиск смысла и самостоятельное мышление.'
  when '8' then 'Сила воли, управление ресурсами, амбиции и материальная реализация.'
  when '9' then 'Широкий взгляд, эмпатия, идеалы и желание приносить пользу.'
  when '11' then 'Сильная интуиция, чувствительность и способность видеть связи глубже очевидного.'
  when '22' then 'Масштабное мышление и способность превращать большие идеи в конкретные системы.'
  when '33' then 'Забота о людях, зрелость, вдохновение и стремление создавать ценность для других.'
 end,
 relationships = case key
  when '1' then 'В отношениях важно сохранять самостоятельность. Тебе подходит союз двух взрослых людей, где есть уважение к границам и инициативе.'
  when '2' then 'Тебе важны эмоциональная близость, мягкость и ощущение, что тебя действительно слышат. Холодность может ранить сильнее, чем кажется.'
  when '3' then 'Связь раскрывается через общение, юмор и совместные впечатления. Важно не прятать серьёзные чувства за лёгкостью.'
  when '4' then 'Надёжность важнее красивых обещаний. Любовь для тебя часто проявляется через поступки, заботу и присутствие рядом.'
  when '5' then 'Нужны живость и пространство. Слишком жёсткие рамки быстро гасят интерес, поэтому особенно важны доверие и свобода.'
  when '6' then 'Есть сильная потребность в тёплом доме и настоящей близости. Важно не превращать заботу в контроль.'
  when '7' then 'Нужно время, чтобы по-настоящему открыться. Поверхностность утомляет, зато глубокая связь может быть очень крепкой.'
  when '8' then 'Притягивают сильные и самостоятельные люди. В паре важно заранее договариваться о власти, деньгах и личном пространстве.'
  when '9' then 'Важны душевность, смысл и ощущение общего пути. Стоит следить, чтобы идеализация не подменяла реального человека.'
  when '11' then 'Чувства могут восприниматься очень тонко. Нужны честность, бережность и партнёр, рядом с которым не приходится постоянно защищаться.'
  when '22' then 'Отношения воспринимаются как совместное строительство жизни. Хорошо работает союз, где мечты превращаются в понятные планы.'
  when '33' then 'Есть сильная потребность отдавать тепло. Важно помнить о себе и не брать на себя роль спасателя.'
 end,
 money = case key
  when '1' then 'Деньги лучше раскрываются там, где есть личная ответственность, самостоятельные решения и возможность вести за собой.'
  when '2' then 'Сильны партнёрские модели, переговоры, сервис и сферы, где ценится умение работать с людьми.'
  when '3' then 'Доход может быть связан с коммуникацией, контентом, продажами, творчеством и публичностью.'
  when '4' then 'Сильная сторона в стабильных системах, управлении процессами, строительстве, технике и долгосрочных проектах.'
  when '5' then 'Подходят динамичные сферы, продажи, путешествия, маркетинг, предпринимательство и проекты с постоянным движением.'
  when '6' then 'Хорошо раскрываются сферы сервиса, красоты, дизайна, образования, недвижимости и заботы о людях.'
  when '7' then 'Ценность создаётся через знания, аналитику, исследования, технологии и экспертность.'
  when '8' then 'Есть потенциал для управления крупными ресурсами, бизнеса, финансов и руководящих ролей.'
  when '9' then 'Деньги могут приходить через масштабные проекты, творчество, помощь людям и работу с широкой аудиторией.'
  when '11' then 'Особенно важна работа, где интуиция и идеи превращаются в понятную ценность для других.'
  when '22' then 'Сильная тема больших проектов, систем, бизнеса и решений, которые работают не только на одного человека.'
  when '33' then 'Лучше всего раскрывается деятельность, где польза людям соединяется с профессиональной системой, а не с самопожертвованием.'
 end,
 realization = case key
  when '1' then 'Реализация через инициативу, самостоятельные проекты и право принимать решения.'
  when '2' then 'Реализация через партнёрство, переговоры, командную работу и тонкое понимание людей.'
  when '3' then 'Реализация через слово, творчество, обучение, коммуникацию и личную выразительность.'
  when '4' then 'Реализация через дисциплину, мастерство, систему и последовательное накопление результата.'
  when '5' then 'Реализация через изменения, новые рынки, движение и способность быстро адаптироваться.'
  when '6' then 'Реализация через создание качества, красоты, порядка и заботы.'
  when '7' then 'Реализация через знания, исследование, точность и способность увидеть суть.'
  when '8' then 'Реализация через управление, ответственность, масштаб и материальный результат.'
  when '9' then 'Реализация через смысл, творчество, широкую аудиторию и пользу людям.'
  when '11' then 'Реализация через идеи, интуицию и способность вдохновлять других.'
  when '22' then 'Реализация через крупные системы, проекты и превращение идеи в работающую конструкцию.'
  when '33' then 'Реализация через зрелое наставничество, заботу и создание среды, в которой растут другие.'
 end,
 purpose = case key
  when '1' then 'Научиться быть автором собственной жизни, не ожидая разрешения со стороны.'
  when '2' then 'Учиться сотрудничать, сохраняя собственную ценность и границы.'
  when '3' then 'Находить свой голос и не бояться показывать миру то, что создаёшь.'
  when '4' then 'Строить устойчивую основу и доводить важное до результата.'
  when '5' then 'Использовать свободу осознанно, а не бежать от каждой скучной ситуации.'
  when '6' then 'Создавать гармонию без привычки тащить на себе всех вокруг.'
  when '7' then 'Превращать глубокое понимание в реальный опыт и действие.'
  when '8' then 'Учиться обращаться с силой и ресурсами без потери человеческой стороны.'
  when '9' then 'Соединять личный путь с чем-то большим, не растворяясь в чужих проблемах.'
  when '11' then 'Доверять интуиции, но проверять идеи реальностью.'
  when '22' then 'Создавать не только большие замыслы, но и устойчивые результаты.'
  when '33' then 'Помогать другим без отказа от собственной жизни и собственных целей.'
 end,
 practical_advice = case key
  when '1' then 'Выбирай одну важную цель и регулярно делай первый шаг сам.'
  when '2' then 'Говори о своих потребностях прямо, не заставляя других угадывать.'
  when '3' then 'Давай себе пространство для творчества и чаще доводи идеи до законченного результата.'
  when '4' then 'Строй систему вокруг цели: сроки, привычки и конкретные действия.'
  when '5' then 'Оставляй место переменам, но не принимай важные решения только из-за скуки.'
  when '6' then 'Заботься о других, но оставляй в расписании время, которое принадлежит только тебе.'
  when '7' then 'После анализа переходи к эксперименту. Проверяй мысли реальным опытом.'
  when '8' then 'Считай ресурсы, держи слово и не путай контроль с ответственностью.'
  when '9' then 'Сохраняй границы и выбирай те проекты, где твоя помощь действительно нужна.'
  when '11' then 'Записывай идеи и наблюдения, а затем проверяй их маленькими действиями.'
  when '22' then 'Разбивай большую цель на этапы и назначай каждому конкретный результат.'
  when '33' then 'Помогай там, где это действительно полезно, и не забывай пополнять собственный ресурс.'
 end
where category in ('core','master');

-- Birthday meanings 1-31. These are symbolic interpretations, not scientific claims.
insert into public.numerology_knowledge
(category,key,title,meaning,strengths,challenges,guidance,essence,relationships,money,realization,purpose,practical_advice)
values
('birthday','1','День рождения 1','Инициатива, самостоятельность и желание идти своим путём.','Смелость, решительность, лидерство.','Упрямство, нетерпение, желание всё делать самому.','Учись сочетать самостоятельность с умением принимать помощь.','Энергия старта и личной воли.','Нужны уважение и пространство.','Сильнее раскрывается личная инициатива.','Свои проекты и роли с ответственностью.','Стать автором собственного пути.','Каждый день делай хотя бы один шаг к своей цели.')
,('birthday','2','День рождения 2','Чуткость, дипломатия и внимание к отношениям.','Тактичность, эмпатия, умение договариваться.','Сомнения, зависимость от чужой оценки.','Не прячь собственную позицию ради мира.','Тонкая чувствительность и партнёрство.','Важны тепло и безопасность.','Сильны партнёрские модели.','Командная работа и переговоры.','Сохранять себя внутри отношений.','Говори прямо о том, что тебе нужно.')
,('birthday','3','День рождения 3','Самовыражение, общительность и творческая энергия.','Юмор, речь, фантазия.','Рассеянность, недоведённые дела.','Давай таланту форму и завершай начатое.','Живость и желание выражать себя.','Нужны общение и лёгкость.','Контент, продажи, творчество.','Публичность и коммуникации.','Найти свой голос.','Выбери одну идею и доведи её до результата.')
,('birthday','4','День рождения 4','Практичность, порядок и опора на результат.','Надёжность, дисциплина, терпение.','Жёсткость, страх перемен.','Не превращай порядок в клетку.','Строительная энергия и устойчивость.','Поступки важнее слов.','Стабильные системы и процессы.','Управление и мастерство.','Создать прочную основу.','Составь простой план и придерживайся его.')
,('birthday','5','День рождения 5','Свобода, движение и интерес к новому.','Гибкость, любопытство, адаптация.','Импульсивность, скука, непостоянство.','Свобода работает лучше, когда есть внутренние правила.','Энергия перемен и опыта.','Нужны доверие и воздух.','Продажи, маркетинг, движение.','Динамичные проекты.','Научиться свободе без хаоса.','Перед важной сменой дай себе сутки на решение.')
,('birthday','6','День рождения 6','Забота, ответственность и чувство гармонии.','Тепло, верность, вкус.','Контроль, чувство вины, роль спасателя.','Помогай без отказа от собственных границ.','Создание гармоничной среды.','Сильна потребность в доме и близости.','Сервис, красота, недвижимость.','Создание качественной среды.','Заботиться без самопотери.','Раз в неделю делай что-то только для себя.')
,('birthday','7','День рождения 7','Наблюдательность, глубина и самостоятельное мышление.','Анализ, интуиция, исследовательский интерес.','Закрытость, чрезмерный анализ.','Не жди полной ясности перед действием.','Поиск сути.','Открываешься постепенно.','Знания, аналитика, технологии.','Экспертность.','Соединить понимание с опытом.','Проверяй одну мысль практикой.')
,('birthday','8','День рождения 8','Амбиция, сила и умение обращаться с ресурсами.','Организация, воля, масштаб.','Жёсткость, чрезмерный контроль.','Сила становится устойчивой, когда есть ответственность.','Энергия управления и результата.','Важны равенство и уважение.','Бизнес, финансы, управление.','Масштабные задачи.','Научиться управлять ресурсом.','Разделяй контроль и ответственность.')
,('birthday','9','День рождения 9','Широкий взгляд, идеалы и эмоциональная глубина.','Эмпатия, щедрость, творчество.','Идеализация, эмоциональное выгорание.','Не бери на себя чужую жизнь.','Завершение и широкий смысл.','Нужна душевная честность.','Творчество и социальные проекты.','Работа с широкой аудиторией.','Сохранять человечность и границы.','Помогай только там, где помощь действительно нужна.')
,('birthday','10','День рождения 10','Сочетание самостоятельности и нового цикла.','Инициатива, способность начинать заново.','Нетерпение, резкие старты.','Начинай смелее, но держи направление.','Новый виток через личную волю.','Нужны уважение и свобода.','Сильна самостоятельная деятельность.','Проекты с личной ответственностью.','Создавать собственные возможности.','Не бросай начатое после первого сопротивления.')
,('birthday','11','День рождения 11','Интуиция, впечатлительность и сильное внутреннее ощущение людей.','Вдохновение, чувствительность, идеи.','Перегрузка, сомнения, эмоциональные качели.','Заземляй интуицию конкретными действиями.','Тонкое восприятие.','Нужна бережность.','Идеи, творчество, коммуникации.','Вдохновляющие проекты.','Соединить чувствительность и ясность.','Записывай ощущения и проверяй их фактами.')
,('birthday','12','День рождения 12','Коммуникация, обучение и опыт через отношения.','Общительность, наблюдательность, гибкость.','Зависимость от одобрения.','Не меняй себя ради реакции окружающих.','Обучение через людей и опыт.','Важна обратная связь.','Коммуникации и обучение.','Работа с людьми.','Развить собственный голос.','Перед решением спроси себя, чего хочешь именно ты.')
,('birthday','13','День рождения 13','Практичность и преобразование через труд.','Выносливость, мастерство, системность.','Ощущение тяжести, сопротивление дисциплине.','Результат приходит через последовательность.','Преобразование через работу.','Надёжность важнее эффектности.','Процессы, ремесло, системы.','Постепенный рост.','Создать устойчивый результат.','Делай маленькие шаги ежедневно.')
,('birthday','14','День рождения 14','Свобода и опыт через перемены.','Адаптивность, любознательность.','Импульсивность, крайности.','Свобода требует самодисциплины.','Движение и баланс.','Нужны доверие и личное пространство.','Продажи, путешествия, динамика.','Проекты с переменами.','Научиться управлять свободой.','Сначала правила, потом эксперименты.')
,('birthday','15','День рождения 15','Притягательность, забота и сила влияния.','Харизма, тепло, вкус.','Манипулятивность, эмоциональная зависимость.','Влияй честно и не контролируй близких.','Магнетизм и ответственность за влияние.','Сильное притяжение.','Сервис, красота, коммуникации.','Личный бренд.','Использовать влияние экологично.','Говори о желаниях прямо.')
,('birthday','16','День рождения 16','Глубокое переосмысление и поиск внутренней опоры.','Проницательность, самостоятельность.','Закрытость, резкие внутренние переломы.','Не разрушай всё только ради нового начала.','Пересборка убеждений.','Нужна честность без драматизации.','Знания и экспертность.','Глубокие профессиональные области.','Строить опору внутри себя.','После ошибки записывай вывод и следующий шаг.')
,('birthday','17','День рождения 17','Амбиция, самостоятельность и умение собирать ресурс.','Целеустремлённость, организованность.','Жёсткость, фиксация на результате.','Помни о людях, пока идёшь к цели.','Сила через ответственность.','Уважение важнее контроля.','Управление и бизнес.','Руководство.','Соединить результат и человечность.','Оценивай не только цель, но и цену пути.')
,('birthday','18','День рождения 18','Сильные эмоции, интуиция и широкий социальный взгляд.','Сопереживание, воображение.','Перепады настроения, идеализация.','Отделяй чувства от фактов.','Эмоциональная глубина.','Нужна ясность.','Творческие и социальные проекты.','Работа с людьми.','Сохранять ясность в сильных чувствах.','Не принимай финансовых решений на эмоциях.')
,('birthday','19','День рождения 19','Самостоятельность и опыт ответственности за выбор.','Воля, инициативность.','Упрямство, нежелание просить помощи.','Сила не исключает сотрудничество.','Самостоятельность с уроком зрелости.','Нужны равноправие и уважение.','Собственные проекты.','Личная ответственность.','Стать сильным без изоляции.','Учись принимать помощь без ощущения долга.')
,('birthday','20','День рождения 20','Чувствительность, наблюдательность и потребность в гармонии.','Дипломатия, интуиция.','Сомнения, зависимость от атмосферы.','Создавай внутреннюю опору.','Тонкое ощущение людей.','Важны спокойствие и доверие.','Партнёрские сферы.','Командная работа.','Сохранять себя среди других.','Принимай решения после паузы, а не под давлением.')
,('birthday','21','День рождения 21','Коммуникация, социальность и способность объединять людей.','Харизма, речь, оптимизм.','Рассеянность, зависимость от внимания.','Пусть общительность служит цели.','Открытость и самовыражение.','Нужны живость и уважение.','Продажи, медиа, маркетинг.','Публичные проекты.','Объединять людей через слово.','Каждую неделю заканчивай один отложенный проект.')
,('birthday','22','День рождения 22','Масштабное мышление и способность создавать системы.','Организация, стратегия, выдержка.','Перегрузка, завышенные требования.','Большую цель нужно переводить в этапы.','Архитектура больших результатов.','Союз строится вокруг общих целей.','Бизнес и крупные проекты.','Системное создание результата.','Строить то, что переживёт момент.','Раздели большую цель на ближайшие три шага.')
,('birthday','23','День рождения 23','Свобода, общение и быстрое освоение нового.','Гибкость, интеллект, коммуникация.','Непостоянство, импульсивность.','Направляй любопытство в конкретный результат.','Живой ум и движение.','Нужны разговор и свобода.','Продажи, маркетинг, путешествия.','Динамичные проекты.','Учиться через опыт.','Выбирай один главный вектор на месяц.')
,('birthday','24','День рождения 24','Забота, ответственность и потребность создавать уют.','Верность, практичность, тепло.','Контроль, перегрузка ответственностью.','Не путай любовь с обязанностью всё исправлять.','Создание устойчивой среды.','Сильна семейная тема.','Сервис, недвижимость, красота.','Создание комфортных систем.','Создавать дом и опору без самопожертвования.','Оставляй время на собственные планы.')
,('birthday','25','День рождения 25','Анализ, интуиция и свобода мышления.','Наблюдательность, интеллект.','Скепсис, уход в себя.','Не превращай осторожность в изоляцию.','Исследование и самостоятельность.','Открываешься постепенно.','Аналитика и технологии.','Экспертные задачи.','Доверять себе и миру одновременно.','Обсуждай идеи с человеком, которому доверяешь.')
,('birthday','26','День рождения 26','Амбиция, ответственность и тема управления ресурсами.','Организация, практичность, сила.','Контроль, давление на себя.','Строй систему, которая поддерживает тебя, а не выжимает.','Материальная зрелость.','Нужны договорённости и уважение.','Бизнес и управление.','Ответственные роли.','Научиться владеть ресурсом без его рабства.','Планируй отдых так же серьёзно, как работу.')
,('birthday','27','День рождения 27','Эмпатия, глубина и стремление видеть более широкий смысл.','Интуиция, мудрость, творчество.','Идеализация, эмоциональное истощение.','Не спасай тех, кто не просит помощи.','Глубокое понимание людей.','Важна душевная честность.','Творчество, обучение, социальные сферы.','Проекты со смыслом.','Соединять глубину и границы.','Выбирай, кому и сколько своей энергии отдавать.')
,('birthday','28','День рождения 28','Самостоятельность, партнёрство и ответственность за результат.','Лидерство, адаптивность.','Соперничество, резкость.','Учись выигрывать вместе, а не только один.','Личная сила через взаимодействие.','Нужен равный партнёр.','Предпринимательство и управление.','Собственные проекты.','Соединить независимость и сотрудничество.','Важные решения обсуждай до конфликта.')
,('birthday','29','День рождения 29','Сильная чувствительность, интуиция и эмоциональная глубина.','Эмпатия, вдохновение, тонкое восприятие.','Перегрузка, тревожность, идеализация.','Опирайся на факты и режим, когда эмоций слишком много.','Глубокая восприимчивость.','Нужны доверие и бережность.','Творчество и работа с людьми.','Вдохновляющие проекты.','Научиться превращать чувствительность в силу.','Сначала успокойся, потом принимай важное решение.')
,('birthday','30','День рождения 30','Творческое самовыражение и умение видеть жизнь легче.','Речь, юмор, воображение.','Поверхностность, откладывание.','Свобода раскрывается через завершённые дела.','Лёгкость и выразительность.','Важны игра и общение.','Медиа, контент, продажи.','Публичные и творческие задачи.','Делиться своим видением.','Делай творчество регулярной привычкой.')
,('birthday','31','День рождения 31','Практичность, самостоятельность и способность строить долгий результат.','Дисциплина, выдержка, ответственность.','Упрямство, излишняя серьёзность.','Оставляй место гибкости и удовольствию.','Устойчивое созидание.','Верность проявляется поступками.','Системный бизнес и управление.','Долгосрочные проекты.','Создать прочную основу для будущего.','Каждую неделю проверяй прогресс, а не только планы.')
on conflict (category,key) do update set
 title=excluded.title, meaning=excluded.meaning, strengths=excluded.strengths,
 challenges=excluded.challenges, guidance=excluded.guidance, essence=excluded.essence,
 relationships=excluded.relationships, money=excluded.money, realization=excluded.realization,
 purpose=excluded.purpose, practical_advice=excluded.practical_advice;
